/*
 * Emblemen van de krijgsmachtdelen (OPCO), zonder achtergrond, voor het cadetprofiel.
 * kmaOpcoIcon('CLAS') geeft een <img>; onbekend of leeg geeft ''.
 */
(function () {
  'use strict';
  var E = {
    clas: { t: 'CLAS, Koninklijke Landmacht', w: 105, h: 128, src: 'data:image/png;base64,' },
    czsk: { t: 'CZSK, Koninklijke Marine', w: 66, h: 128, src: 'data:image/png;base64,' },
    clrs: { t: 'CLRS, Lucht- en Ruimtestrijdkrachten', w: 98, h: 128, src: 'data:image/png;base64,' },
    kmar: { t: 'KMar, Koninklijke Marechaussee', w: 78, h: 128, src: 'data:image/png;base64,' }
  };
  function key(v) {
    v = String(v || '').trim();
    if (/^CLAS\b|landmacht/i.test(v)) return 'clas';
    if (/^CZSK\b|marine/i.test(v)) return 'czsk';
    if (/^(CLRS|CLSK|KLu)\b|lucht/i.test(v)) return 'clrs';
    if (/^KMar\b|marechaussee/i.test(v)) return 'kmar';
    return '';
  }
  window.kmaOpcoKey = key;
  /** Emblem with the name of the OPCO next to it (dossier). */
  window.kmaOpcoBadge = function (v) {
    var e = E[key(v)];
    return e ? '<div class="kma-opco-badge">' + window.kmaOpcoIcon(v) + '<span>' + e.t + '</span></div>' : '';
  };
  window.kmaOpcoIcon = function (v, cls) {
    var e = E[key(v)];
    return e ? '<img class="kma-opco-ic' + (cls ? ' ' + cls : '') + '" src="' + e.src + '" alt="' + e.t + '" title="' + e.t + '" width="' + e.w + '" height="' + e.h + '">' : '';
  };
})();
